// Sea, river and lake surface (art §3.11): one plane at WATER_LEVEL under the whole world — wherever the city has
// no ground (water plots) or the terrain dips below the waterline (coast, river channels), water shows. The only
// MeshStandardMaterial in the scene besides ULTRA glass (Standard costs +4.4 ms on the UHD 630, so it is kept to
// the water's pixels; the depth pre-pass rejects the plane under land and buildings).
//
// - Colour: mix(shallow #5FAFC4, deep #2F6F93, smoothstep(0, 40 m, shore)); foam #EAF4F4 bands where shore < ~3 m.
//   `shore` (distance to land) comes from two signed distance fields baked at load: 8 m texels around the city,
//   32 m texels over the outskirts.
// - Two octaves of analytic wave normals (fading with pixel footprint so they never alias), roughness 0.22.
// - Reflections: a PMREM of the sky dome, regenerated by Environment when the hour moves > 20 visual minutes.
// - Bank skirts: vertical faces along in-city water/land plot edges hide the gap between ground (y = 0) and water.
// No planar reflections (Water.js / Reflector render the scene twice).
import * as THREE from 'three';
import { GeoBuilder, toBufferGeometry, type RGB } from '../assets/GeoBuilder';
import { FLAG_SNOWABLE } from '../materials/CityMaterial';
import { PLOT_SIZE } from '../units';
import { TerrainModel, WATER_LEVEL } from './Terrain';
import { WATER_NONE, WATER_SEA, waterAt } from './World';
import type { GroundRect } from './ShadowFit';

const FINE_TEXEL = 8;
const COARSE_TEXEL = 32;
const FINE_MARGIN = 21 * PLOT_SIZE;           // 504 m: whole plots, so plot edges fall on texel edges
/** R8 encoding of the signed shore distance: v = (d + OFFSET) / RANGE. */
const SHORE_OFFSET = 8;
const SHORE_RANGE = 108;

interface ShoreField { texture: THREE.DataTexture; rect: GroundRect }

/** Two-pass chamfer distance (1, √2) in texels to the nearest land texel (mask 1). */
export function chamferDistance(land: Uint8Array, w: number, h: number): Float32Array {
  const INF = 1e9, D = Math.SQRT2;
  const d = new Float32Array(w * h);
  for (let i = 0; i < d.length; i++) d[i] = land[i] ? 0 : INF;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const i = y * w + x;
      let v = d[i];
      if (v === 0) continue;
      if (x > 0) v = Math.min(v, d[i - 1] + 1);
      if (y > 0) {
        v = Math.min(v, d[i - w] + 1);
        if (x > 0) v = Math.min(v, d[i - w - 1] + D);
        if (x < w - 1) v = Math.min(v, d[i - w + 1] + D);
      }
      d[i] = v;
    }
  }
  for (let y = h - 1; y >= 0; y--) {
    for (let x = w - 1; x >= 0; x--) {
      const i = y * w + x;
      let v = d[i];
      if (v === 0) continue;
      if (x < w - 1) v = Math.min(v, d[i + 1] + 1);
      if (y < h - 1) {
        v = Math.min(v, d[i + w] + 1);
        if (x < w - 1) v = Math.min(v, d[i + w + 1] + D);
        if (x > 0) v = Math.min(v, d[i + w - 1] + D);
      }
      d[i] = v;
    }
  }
  return d;
}

function bakeShoreField(rect: GroundRect, texel: number, isLand: (x: number, z: number) => boolean): ShoreField {
  const w = Math.max(2, Math.round((rect.maxX - rect.minX) / texel));
  const h = Math.max(2, Math.round((rect.maxZ - rect.minZ) / texel));
  const land = new Uint8Array(w * h);
  for (let j = 0; j < h; j++) {
    const z = rect.minZ + (j + 0.5) * texel;
    for (let i = 0; i < w; i++) land[j * w + i] = isLand(rect.minX + (i + 0.5) * texel, z) ? 1 : 0;
  }
  const dist = chamferDistance(land, w, h);
  const data = new Uint8Array(w * h);
  for (let i = 0; i < data.length; i++) {
    // Signed: land texels sit half a texel inside the shore, water texels half a texel less than their centre
    // distance, so bilinear filtering crosses zero on the actual waterline.
    const d = land[i] ? -texel / 2 : dist[i] * texel - texel / 2;
    data[i] = Math.round(Math.min(1, Math.max(0, (d + SHORE_OFFSET) / SHORE_RANGE)) * 255);
  }
  const texture = new THREE.DataTexture(data, w, h, THREE.RedFormat, THREE.UnsignedByteType);
  // One byte per texel and arbitrary widths: rows are not 4-byte aligned (the WebGL default would shear the field).
  texture.unpackAlignment = 1;
  texture.colorSpace = THREE.NoColorSpace;
  texture.magFilter = THREE.LinearFilter;
  texture.minFilter = THREE.LinearFilter;
  texture.wrapS = texture.wrapT = THREE.ClampToEdgeWrapping;
  texture.generateMipmaps = false;
  texture.flipY = false;
  texture.needsUpdate = true;
  return { texture, rect };
}

export class WaterSurface {
  readonly group = new THREE.Group();
  readonly material: THREE.MeshStandardMaterial;
  readonly uniforms = {
    uTime: { value: 0 },
    /** 0..1 overcast: greys the water out under cloud (Environment drives it from the weather). */
    uOvercast: { value: 0 },
    uShallow: { value: new THREE.Color('#5FAFC4') },
    uDeep: { value: new THREE.Color('#2F6F93') },
    uFoam: { value: new THREE.Color('#EAF4F4') },
    uShoreFine: { value: null as THREE.Texture | null },
    uShoreFineRect: { value: new THREE.Vector4() },
    uShoreCoarse: { value: null as THREE.Texture | null },
    uShoreCoarseRect: { value: new THREE.Vector4() },
  };
  /** True when the world has any visible water (no sea, river or lake: nothing is added to the scene). */
  readonly hasWater: boolean;
  private readonly mesh: THREE.Mesh | null = null;
  private readonly banks: THREE.Mesh | null = null;
  private readonly fields: ShoreField[] = [];

  constructor(terrain: TerrainModel, cityMaterial: THREE.Material) {
    this.group.name = 'water';
    const world = terrain.world;
    // roughness 0.3 (art: 0.22) and a softer environment keep the sun glitter from turning into noise at 1080p.
    this.material = new THREE.MeshStandardMaterial({ color: '#2F6F93', roughness: 0.3, metalness: 0, envMapIntensity: 0.6 });
    this.material.name = 'MagnateWater';
    const hasCityWater = !!world.water && world.water.some((k) => k !== WATER_NONE);
    // Outskirts water exists only next to coasts/river mouths, which require city water, so this test is complete.
    this.hasWater = hasCityWater;
    if (!this.hasWater) return;

    const r = terrain.rect;
    const fineRect = { minX: r.minX - FINE_MARGIN, maxX: r.maxX + FINE_MARGIN, minZ: r.minZ - FINE_MARGIN, maxZ: r.maxZ + FINE_MARGIN };
    const e = terrain.extent;
    const isLand = (x: number, z: number) => terrain.isLand(x, z);
    this.fields.push(bakeShoreField(fineRect, FINE_TEXEL, isLand), bakeShoreField({ minX: -e, maxX: e, minZ: -e, maxZ: e }, COARSE_TEXEL, isLand));
    const [fine, coarse] = this.fields;
    this.uniforms.uShoreFine.value = fine.texture;
    this.uniforms.uShoreFineRect.value.set(fine.rect.minX, fine.rect.minZ, fine.rect.maxX - fine.rect.minX, fine.rect.maxZ - fine.rect.minZ);
    this.uniforms.uShoreCoarse.value = coarse.texture;
    this.uniforms.uShoreCoarseRect.value.set(-e, -e, 2 * e, 2 * e);

    this.material.onBeforeCompile = (shader) => {
      Object.assign(shader.uniforms, this.uniforms);
      shader.vertexShader = shader.vertexShader
        .replace('#include <common>', '#include <common>\nvarying vec3 vWaterWorld;')
        .replace('#include <project_vertex>', '#include <project_vertex>\nvWaterWorld = (modelMatrix * vec4(transformed, 1.0)).xyz;');
      shader.fragmentShader = shader.fragmentShader
        .replace('#include <common>', `#include <common>
varying vec3 vWaterWorld;
uniform float uTime, uOvercast;
uniform vec3 uShallow, uDeep, uFoam;
uniform sampler2D uShoreFine, uShoreCoarse;
uniform vec4 uShoreFineRect, uShoreCoarseRect;
float waterShore(vec2 p) {
  vec2 f = (p - uShoreFineRect.xy) / uShoreFineRect.zw;
  if (all(greaterThan(f, vec2(0.0))) && all(lessThan(f, vec2(1.0)))) return texture2D(uShoreFine, f).r * ${SHORE_RANGE.toFixed(1)} - ${SHORE_OFFSET.toFixed(1)};
  vec2 c = clamp((p - uShoreCoarseRect.xy) / uShoreCoarseRect.zw, 0.0, 1.0);
  return texture2D(uShoreCoarse, c).r * ${SHORE_RANGE.toFixed(1)} - ${SHORE_OFFSET.toFixed(1)};
}`)
        .replace('#include <color_fragment>', `#include <color_fragment>
{
  float shore = max(waterShore(vWaterWorld.xz), 0.0);
  diffuseColor.rgb = mix(uShallow, uDeep, smoothstep(0.0, 30.0, shore));
  // Under cloud the water loses its colour towards a cool slate grey.
  float wl = dot(diffuseColor.rgb, vec3(0.2126, 0.7152, 0.0722));
  diffuseColor.rgb = mix(diffuseColor.rgb, wl * vec3(0.92, 1.0, 1.08), 0.6 * uOvercast);
  float foam = (1.0 - smoothstep(0.5, 3.5, shore)) * (0.55 + 0.45 * step(fract(shore * 0.25 - uTime * 0.3), 0.15));
  foam *= 1.0 - smoothstep(700.0, 1600.0, distance(vWaterWorld, cameraPosition));
  diffuseColor.rgb = mix(diffuseColor.rgb, uFoam, foam * 0.85);
}`)
        .replace('#include <normal_fragment_maps>', `#include <normal_fragment_maps>
{
  // Four directional sine waves (gradients only), amplitude fading with the pixel footprint so they never alias.
  vec2 p = vWaterWorld.xz;
  float fw = length(fwidth(p));
  float a1 = 0.035 * (1.0 - smoothstep(2.0, 8.0, fw));
  float a2 = 0.022 * (1.0 - smoothstep(0.8, 3.0, fw));
  vec2 d1 = vec2(0.94, 0.34), d2 = vec2(-0.42, 0.91), d3 = vec2(0.71, -0.70), d4 = vec2(-0.88, -0.47);
  vec2 g = a1 * (d1 * cos(dot(p, d1) * 0.31 + uTime * 0.8) + d2 * cos(dot(p, d2) * 0.43 - uTime * 0.95))
         + a2 * (d3 * cos(dot(p, d3) * 0.97 + uTime * 1.5) + d4 * cos(dot(p, d4) * 1.31 - uTime * 1.7));
  normal = normalize((viewMatrix * vec4(normalize(vec3(-g.x, 1.0, -g.y)), 0.0)).xyz);
}`);
    };
    this.material.customProgramCacheKey = () => 'magnate-water-v2';

    const plane = new THREE.PlaneGeometry(2 * e, 2 * e, 1, 1).rotateX(-Math.PI / 2);
    const mesh = new THREE.Mesh(plane, this.material);
    mesh.name = 'water-surface';
    mesh.position.y = WATER_LEVEL;
    mesh.updateMatrix();
    mesh.matrixAutoUpdate = false;
    mesh.receiveShadow = true;
    mesh.castShadow = false;
    mesh.renderOrder = 1;                       // after terrain and chunks: early-z rejects the plane under land
    this.mesh = mesh;
    this.group.add(mesh);

    const banks = this.buildBanks(terrain);
    if (banks) {
      this.banks = new THREE.Mesh(banks, cityMaterial);
      this.banks.name = 'water-banks';
      this.banks.receiveShadow = true;
      this.banks.matrixAutoUpdate = false;
      this.group.add(this.banks);
    }
  }

  /** Vertical faces from the ground down below the waterline along every in-city water/land plot edge. */
  private buildBanks(terrain: TerrainModel): THREE.BufferGeometry | null {
    const world = terrain.world;
    if (!world.water) return null;
    const b = new GeoBuilder();
    b.flags = FLAG_SNOWABLE;
    b.tint = 0;
    const sand: RGB = [0xd8, 0xc7, 0x9a], earth: RGB = [0x8a, 0x7f, 0x62];
    const y0 = WATER_LEVEL - 0.8, y1 = 0.02;
    const { minX, minZ } = terrain.rect;
    for (let pz = 0; pz < world.gridH; pz++) {
      for (let px = 0; px < world.gridW; px++) {
        const kind = waterAt(world, px, pz);
        if (kind === WATER_NONE) continue;
        const col = kind === WATER_SEA ? sand : earth;
        const x0 = minX + px * PLOT_SIZE, x1 = x0 + PLOT_SIZE, z0 = minZ + pz * PLOT_SIZE, z1 = z0 + PLOT_SIZE;
        const land = (qx: number, qz: number) => qx >= 0 && qz >= 0 && qx < world.gridW && qz < world.gridH && waterAt(world, qx, qz) === WATER_NONE;
        // Each face points into the water plot (towards the viewer looking at the bank from the water side).
        // Windings match GeoBuilder.box faces with the same normals (counter-clockwise seen from the normal side).
        if (land(px, pz - 1)) b.quad([x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0], [0, 0, 1], col);
        if (land(px, pz + 1)) b.quad([x1, y0, z1], [x0, y0, z1], [x0, y1, z1], [x1, y1, z1], [0, 0, -1], col);
        if (land(px - 1, pz)) b.quad([x0, y0, z1], [x0, y0, z0], [x0, y1, z0], [x0, y1, z1], [1, 0, 0], col);
        if (land(px + 1, pz)) b.quad([x1, y0, z0], [x1, y0, z1], [x1, y1, z1], [x1, y1, z0], [-1, 0, 0], col);
      }
    }
    if (b.triangleCount === 0) return null;
    return toBufferGeometry(b.finish());
  }

  setEnvMap(texture: THREE.Texture | null): void {
    if (this.material.envMap === texture) return;
    const hadMap = this.material.envMap !== null;
    this.material.envMap = texture;
    if (hadMap !== (texture !== null)) this.material.needsUpdate = true;
  }

  /** Per frame: wave time and overcast amount (0..1). */
  update(timeSec: number, overcast = 0): void {
    this.uniforms.uTime.value = timeSec;
    this.uniforms.uOvercast.value = overcast;
  }

  dispose(): void {
    this.mesh?.geometry.dispose();
    this.banks?.geometry.dispose();
    this.material.dispose();
    for (const f of this.fields) f.texture.dispose();
    this.group.removeFromParent();
  }
}
